test('the exact publishing Preview admits only canonical Community posts and reactions',async()=>{
 const current=publishingWorker();
 assert.deepEqual(await request('/rest/v1/rpc/add_contribution',{workerSource:current,headers:managementHeaders,body:publicPost}),{status:200,forwarded:2,blocked:null});
 assert.deepEqual(await request('/rest/v1/rpc/toggle_contribution_reaction',{workerSource:current,headers:managementHeaders,body:{p_id:managementId,p_emoji:'👍',p_visitor:null}}),{status:200,forwarded:1,blocked:null});
 for(const deniedWorker of [worker,managementWorker(),managementWorker(publishingBranch,'production')]){
  assert.equal((await request('/rest/v1/rpc/add_contribution',{workerSource:deniedWorker,headers:managementHeaders,body:publicPost})).status,403);
  assert.equal((await request('/rest/v1/rpc/toggle_contribution_reaction',{workerSource:deniedWorker,headers:managementHeaders,body:{p_id:managementId,p_emoji:'👍',p_visitor:null}})).status,403);
 }
 for(const bad of [{...publicPost,p_origin:'broadcast'},{...publicPost,p_intent:'מקור'},{...publicPost,p_target_id:'private'},{...publicPost,p_author_user_id:managementId},{...publicPost,p_body:''},{...publicPost,p_body:'x'.repeat(6001)}]){
  const result=await request('/rest/v1/rpc/add_contribution',{workerSource:current,headers:managementHeaders,body:bad});assert.equal(result.status,403);assert.equal(result.forwarded,0);
 }
 const guest=await request('/rest/v1/rpc/add_contribution',{workerSource:current,headers:managementHeaders,body:publicPost,serverUser:null});assert.equal(guest.status,403);assert.equal(guest.forwarded,1);
 for(const extra of [{p_emoji:'👎',p_visitor:null},{p_emoji:'👍',p_visitor:'forged-visitor'}])assert.equal((await request('/rest/v1/rpc/toggle_contribution_reaction',{workerSource:current,headers:managementHeaders,body:{p_id:managementId,...extra}})).status,403);
});

test('account-scoped media uploads validate the file and server-authenticated owner without allowing overwrite',async()=>{
 const current=publishingWorker(),path='/storage/v1/object/gallery/community/'+managementId+'/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb.mp4';
 const form=()=>{const value=new FormData();value.append('cacheControl','3600');value.append('',new File(['video fixture'],'clip.mp4',{type:'video/mp4'}));return value;};
 const headers={...managementHeaders,'x-upsert':'false',apikey:'public-fixture'};
 assert.deepEqual(await request(path,{workerSource:current,headers,rawBody:form()}),{status:200,forwarded:2,blocked:null});
 for(const badHeaders of [{...headers,'x-upsert':'true'},{...headers,Authorization:'Basic fake'}])assert.equal((await request(path,{workerSource:current,headers:badHeaders,rawBody:form()})).status,403);
 for(const serverUser of [null,'cccccccc-cccc-4ccc-8ccc-cccccccccccc'])assert.equal((await request(path,{workerSource:current,headers,rawBody:form(),serverUser})).status,403);
 for(const badPath of [path.replace(managementId+'/',''),path.replace('.mp4','.html'),path+'?upsert=true'])assert.equal((await request(badPath,{workerSource:current,headers,rawBody:form()})).status,403);
 const unsafe=new FormData();unsafe.append('',new File(['<script>'],'clip.mp4',{type:'text/html'}));assert.equal((await request(path,{workerSource:current,headers,rawBody:unsafe})).status,403);
 assert.equal((await request(path,{workerSource:managementWorker(),headers,rawBody:form()})).status,403);
 assert.equal((await request('/auth/v1/settings',{workerSource:current,method:'GET'})).status,200);
 for(const method of ['PUT','DELETE'])assert.equal((await request(path,{workerSource:current,method,headers})).status,403);
});

test('legacy claim transport requires exact branch, confirmed server identity and only a source ID',async()=>{
 const path='/rest/v1/rpc/contributors_claim_legacy',body={p_contributor_id:managementId},opts={body,headers:managementHeaders,workerSource:publishingWorker()};
 assert.deepEqual(await request(path,opts),{status:200,forwarded:2,blocked:null});
 for(const user of [null])assert.equal((await request(path,{...opts,serverUser:user})).status,403);
 assert.equal((await request(path,{...opts,serverConfirmed:false})).status,403);
 for(const invalid of [{...body,p_user_id:managementId},{...body,email:'forged@example.invalid'},{...body,role:'admin'},{p_contributor_id:'אמילי'},null,[]]){
  const r=await request(path,{...opts,body:invalid});assert.equal(r.status,403);assert.equal(r.forwarded,0);
 }
 for(const denied of [worker,managementWorker(),managementWorker(publishingBranch,'production')])assert.equal((await request(path,{...opts,workerSource:denied})).status,403);
 for(const method of ['GET','PUT','DELETE'])assert.equal((await request(path,{...opts,method,body:undefined})).status,403);
 assert.equal((await request(path+'?select=*',opts)).status,403);
});

test('exact own-avatar Preview upload and self action keep all other writes closed',async()=>{
 const uid='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',path='/storage/v1/object/gallery/avatars/'+uid+'-1793440000000.png';
 const form=()=>{const f=new FormData();f.append('cacheControl','3600');f.append('',new Blob(['synthetic'],{type:'image/png'}),'a.png');return f;};
 const opts={workerSource:publishingWorker(),headers:{Authorization:managementHeaders.Authorization,'x-upsert':'false'},rawBody:form()};
 assert.deepEqual(await request(path,opts),{status:200,forwarded:2,blocked:null});
 for(const change of [{serverUser:null},{serverUser:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'},{headers:{...opts.headers,'x-upsert':'true'}},{workerSource:managementWorker()},{workerSource:managementWorker(publishingBranch,'production')}])assert.equal((await request(path,{...opts,...change,rawBody:form()})).status,403);
 const url='https://linswmnnkjxvweumprav.supabase.co/storage/v1/object/public/gallery/avatars/'+uid+'-1793440000000.png';
 const action={origin:'https://preview.invalid',workerSource:publishingWorker(),headers:managementHeaders,body:{action:'avatar',url,publish:true,ack:true}};
 assert.deepEqual(await request('/api/contributor-self',action),{status:200,forwarded:1,blocked:null});
 for(const body of [{...action.body,action:'create'},{...action.body,user_id:uid},{...action.body,publish:false},{...action.body,url:'https://evil.invalid/a.png'}])assert.equal((await request('/api/contributor-self',{...action,body})).status,403);
 assert.equal((await request('/api/contributor-self',{...action,workerSource:managementWorker()})).status,403);
});

test('unified real Raziel Preview forwards only explicit canonical chat to the existing server', async () => {
  const branch='gpt/2029-unified-end-to-end-preview-20261031';
  const makeWorker=env=>vm.runInNewContext(`${source}\nworker;`, { COMMUNITY_UPLOAD_POLICY, AVATAR_UPLOAD_POLICY, process:{env} });
  const workerSource=makeWorker({VERCEL_GIT_COMMIT_REF:branch,VERCEL_ENV:'preview'});
  const headers={Authorization:'Bearer synthetic.synthetic.synthetic','Content-Type':'application/json'};
  const body={kind:'research',persona:'raziel',subject:'מה אפשר לחקור כאן?',research_contract:'public-number-research-run-v1',facts:'',context:'',path:[],again:false,metatron:false};
  assert.deepEqual(await request('/functions/v1/ai-analyze',{headers,body,workerSource}),{status:200,forwarded:1,blocked:null});
  for(const invalid of [{...body,els_matrix_context:{}},{...body,els_matrix_reading_action:{op:'start'}},{...body,els_planning_action:{}},{...body,persona:'other'},{...body,research_contract:null},{...body,subject:''},{...body,subject:'א'.repeat(301)},{...body,operation:'publish'},[]]) {
    assert.deepEqual(await request('/functions/v1/ai-analyze',{headers,body:invalid,workerSource}),{status:403,forwarded:0,blocked:'true'});
  }
  for(const options of [{body},{body,headers:{Authorization:'Bearer invalid'}},{body,headers,method:'PUT'},{rawBody:'{bad',headers}])assert.equal((await request('/functions/v1/ai-analyze',{...options,workerSource})).status,403);
  for(const env of [{VERCEL_GIT_COMMIT_REF:branch,VERCEL_ENV:'production'},{VERCEL_GIT_COMMIT_REF:branch},{VERCEL_GIT_COMMIT_REF:'gpt/unreviewed',VERCEL_ENV:'preview'}])assert.equal((await request('/functions/v1/ai-analyze',{headers,body,workerSource:makeWorker(env)})).status,403);
  for(const path of ['/functions/v1/research-run','/functions/v1/wa-raziel','/functions/v1/els-live-reading','/rest/v1/rpc/research_state_apply_v1','/rest/v1/rpc/fn_get_or_create_my_person','/rest/v1/rpc/add_contribution','/api/contributor-self'])assert.equal((await request(path,{headers,body,workerSource})).status,403,path);
  assert.equal((await request('/api/contributor-self',{headers,body:{action:'avatar',ack:true,publish:true,url:'synthetic'},origin:'https://preview.invalid',workerSource})).status,403);
  for(const rpc of ['research_state_snapshot_v1','fn_research_path_resume_v1','dm_inbox'])assert.equal((await request('/rest/v1/rpc/'+rpc,{headers,body:{},workerSource})).status,200,rpc);
  for(const rpc of ['research_state_apply_v1','fn_research_path_append_v1','dm_thread','dm_send'])assert.equal((await request('/rest/v1/rpc/'+rpc,{headers,body:{},workerSource})).status,403,rpc);
  const prebuild=builder.slice(builder.indexOf('const END_TO_END_BRANCH'),builder.indexOf('const POSTS_PREVIEW_BRANCH'));
  assert.throws(()=>vm.runInNewContext(prebuild,{process:{env:{VERCEL_GIT_COMMIT_REF:branch,VERCEL_ENV:'production'}}}),/unified_preview_is_never_production/);
});


test('reviewed public reply reads require exact projection and a server-confirmed visible parent chain',async()=>{
 const fields='id,parent_id,author_name,author_user_id,author_contributor_id,title,body,reactions,origin,created_at,edited_at,is_deleted,total_count';
 const path='/rest/v1/rpc/community_replies_page?select='+encodeURIComponent(fields);
 const options={workerSource:publishingWorker(),body:{p_parent:managementId,p_offset:0,p_limit:20}};
 assert.deepEqual(await request(path,options),{status:200,forwarded:2,blocked:null});
 assert.deepEqual(await request(path,{...options,replyContext:[]}),{status:200,forwarded:1,blocked:null});
 assert.equal((await request(path,{...options,contextStatus:503})).status,503);
 for(const body of [{...options.body,p_parent:'bad'},{...options.body,p_limit:101},{...options.body,p_offset:-1},{...options.body,p_offset:1.5},{...options.body,extra:true}])assert.equal((await request(path,{...options,body})).status,403);
 for(const workerSource of [worker,managementWorker(),managementWorker(publishingBranch,'production')])assert.equal((await request(path,{...options,workerSource})).status,403);
 for(const wrong of ['/rest/v1/rpc/community_replies_page?select=*',path+'&extra=1','/rest/v1/rpc/community_reply_counts'])assert.equal((await request(wrong,options)).status,403);
});

for (const branch of ['gpt/2029-unified-community-latest-integration-20261031', 'gpt/2029-unified-performance-consolidation-20261031', 'gpt/2029-home-loading-acceptance-20261031']) test(`exact unified branch ${branch} composes reviewed actions with central Raziel without widening other previews`,async()=>{
 const current=managementWorker(branch);
 const fields='id,parent_id,author_name,author_user_id,author_contributor_id,title,body,reactions,origin,created_at,edited_at,is_deleted,total_count';
 const path='/rest/v1/rpc/community_replies_page?select='+encodeURIComponent(fields),body={p_parent:managementId,p_offset:0,p_limit:20};
 for(const[rpc,args]of managementCalls)assert.deepEqual(await request('/rest/v1/rpc/'+rpc,{workerSource:current,headers:managementHeaders,body:args}),{status:200,forwarded:1,blocked:null});
 assert.deepEqual(await request(path,{workerSource:current,body}),{status:200,forwarded:2,blocked:null});
 assert.deepEqual(await request(path,{workerSource:current,body,replyContext:[]}),{status:200,forwarded:1,blocked:null});
 assert.equal((await request(path,{workerSource:current,body,contextStatus:503})).status,503);
 const avatar={origin:'https://preview.invalid',workerSource:current,headers:managementHeaders,body:{action:'avatar',url:'https://linswmnnkjxvweumprav.supabase.co/storage/v1/object/public/gallery/avatars/'+managementId+'-1761868800000.png',ack:true,publish:true}};
 assert.equal((await request('/api/contributor-self',avatar)).status,200);
 for(const invalid of [{...avatar.body,action:'create'},{...avatar.body,user_id:managementId},{...avatar.body,publish:false}])assert.equal((await request('/api/contributor-self',{...avatar,body:invalid})).status,403);
 const chat={kind:'research',persona:'raziel',subject:'מה אפשר לחקור כאן?',research_contract:'public-number-research-run-v1'};
 assert.deepEqual(await request('/functions/v1/ai-analyze',{workerSource:current,headers:managementHeaders,body:chat}),{status:200,forwarded:1,blocked:null});
 for(const extras of [{els_matrix_reading_action:{op:'start'}},{els_matrix_context:{}},{operation:'publish'}])assert.equal((await request('/functions/v1/ai-analyze',{workerSource:current,headers:managementHeaders,body:{...chat,...extras}})).status,403);
 for(const rpc of ['research_state_apply_v1','fn_get_or_create_my_person','dm_thread','community_reply_counts'])assert.equal((await request('/rest/v1/rpc/'+rpc,{workerSource:current,headers:managementHeaders,body:{}})).status,403,rpc);
 for(const wrong of ['/rest/v1/rpc/community_replies_page?select=*',path+'&select=*',path+'&private=1'])assert.equal((await request(wrong,{workerSource:current,body})).status,403);
 for(const denied of [managementWorker(branch,'production'),managementWorker(branch,'development'),managementWorker('gpt/unreviewed-community-preview'),managementWorker(branch+'-other')]){
  assert.equal((await request('/rest/v1/rpc/community_edit_message',{workerSource:denied,headers:managementHeaders,body:{p_id:managementId,p_body:'בדיקה'}})).status,403);
  assert.equal((await request(path,{workerSource:denied,body})).status,403);
  assert.equal((await request('/api/contributor-self',{...avatar,workerSource:denied})).status,403);
  assert.equal((await request('/functions/v1/ai-analyze',{workerSource:denied,headers:managementHeaders,body:chat})).status,403);
 }
 const productionGuard=builder.slice(builder.indexOf('const END_TO_END_BRANCH'),builder.indexOf('const POSTS_PREVIEW_BRANCH'));
 assert.throws(()=>vm.runInNewContext(productionGuard,{process:{env:{VERCEL_GIT_COMMIT_REF:branch,VERCEL_ENV:'production'}}}),/unified_preview_is_never_production/);
});


test('public-foundation Preview retains identity/write boundaries and permits only the existing exact newsletter contract', async () => {
 const branch='gpt/2029-public-foundation-continuity-20261101';
 const current=managementWorker(branch);
 const signup={email:'reader@example.invalid',source:'2029-public-updates'};
 assert.equal((await request('/functions/v1/newsletter-signup?format=json',{body:signup,workerSource:current})).forwarded,1);
 for(const body of [{...signup,source:'other'},{...signup,email:'bad'},{...signup,active:true},[],null]) {
  const result=await request('/functions/v1/newsletter-signup?format=json',{body,workerSource:current});assert.equal(result.status,403);assert.equal(result.forwarded,0);
 }
 for(const path of ['/functions/v1/newsletter-signup','/functions/v1/newsletter-signup?format=json&extra=1']) assert.equal((await request(path,{body:signup,workerSource:current})).status,403);
 for(const [ref,env] of [[branch,'production'],[branch,'development'],[branch,undefined],[branch+'-other','preview'],[functionalBranch,'preview']]) {
  const result=await request('/functions/v1/newsletter-signup?format=json',{body:signup,workerSource:managementWorker(ref,env ?? "")});assert.equal(result.status,403);assert.equal(result.forwarded,0);
 }
 for(const path of ['/rest/v1/profiles','/rest/v1/posts','/rest/v1/subscribers','/rest/v1/rpc/admin_set_role']) {
  const result=await request(path,{body:{role:'admin'},workerSource:current});assert.equal(result.status,403);assert.equal(result.forwarded,0);
 }
 for(const rpc of ['is_number_indexable','is_phrase_indexable'])assert.equal((await request('/rest/v1/rpc/'+rpc,{body:{},workerSource:current})).status,200);
});
